// GENERATED: node scripts/build-shared-mvu-native.mjs --write
(function () {
"use strict";
const ASTERISK_CONTRACT = {
  schools: ['seidoukan', 'gallardworth', 'jielong', 'rewolf', 'arlequint'],
  identities: ['星脉世代', '魔术师', '自定义'],
  ranks: ['未知', '未上榜', '已上榜'],
  weapons: ['尚未确定', '常规武器', '煌式武装', '纯星煌式武装', '研究装备', '不使用武装'],
};

// 原生模式不依赖 Zod；仅检查学战必需数据，未知资料原样保留，不做整档清洗。
function hasAsteriskNativeContract(state) {
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  const text = value => typeof value === 'string';
  const texts = (value, keys) => object(value) && keys.every(key => text(value[key]));
  const names = value => Array.isArray(value) && value.every(item => text(item) && item.length > 0);
  const skills = value => object(value) && Object.values(value).every(skill => text(skill) || object(skill) &&
    ['说明', '条件与代价'].every(key => skill[key] === undefined || text(skill[key])) &&
    (skill.掌握状态 === undefined || ['待确认', '学习中', '已掌握'].includes(skill.掌握状态)));
  if (!isSharedMvuState(state) || resolveMvuWorld(state) !== 'asterisk') return false;
  const player = state.玩家, scene = state.场景, aw = player.学战, rank = aw?.校内序列;
  return player.性别 === '男性' && texts(player, ['姓名', '性格关键词', '处事风格', '所属', '角色简介', '战斗风格']) &&
    (state.系统.开局状态 !== '已建档' || player.姓名.trim().length > 0) &&
    ['当前身体', '当前能力边界', '本局映射'].every(key => player[key] === undefined || text(player[key])) && skills(player.其他能力) &&
    texts(aw, ['能力机制', '共通限制']) && ASTERISK_CONTRACT.schools.includes(aw.学园ID) && ASTERISK_CONTRACT.identities.includes(aw.能力身份) &&
    skills(aw.招式) && texts(aw.星辰力, ['说明']) && object(rank) && ASTERISK_CONTRACT.ranks.includes(rank.状态) &&
    (rank.状态 === '已上榜' ? Number.isInteger(rank.名次) && rank.名次 >= 1 && rank.名次 <= 72 : rank.名次 === null) &&
    texts(aw.武装, ['名称', '使用条件']) && ASTERISK_CONTRACT.weapons.includes(aw.武装.类别) &&
    scene.当前卷 === null && texts(scene, ['当前章', '时间', '地点', '切入说明']) && scene.当前章.trim().length > 0 &&
    ['未开始', '进行中', '已结束', '已完成'].includes(scene.阶段) && object(scene.已发生事件) &&
    Object.values(scene.已发生事件).every(event => texts(event, ['章段', '结果']) && event.章段.length > 0 && event.结果.length > 0 &&
      event.卷号 === null && names(event.参与者) && names(event.知情者)) && (scene.日程 === undefined || object(scene.日程));
}

// 作品标记与外观无关；仅旧的已建档 v4 缺标记时按落第解释。
function resolveMvuWorld(state) {
  const system = state?.系统;
  if (!system || typeof system !== 'object' || Array.isArray(system)) return null;
  if (Object.hasOwn(system, '作品')) return ['rakudai', 'asterisk'].includes(system.作品) ? system.作品 : null;
  return system.结构版本 === 4 && system.开局状态 === '已建档' &&
    ['场景', '玩家', '人际'].every(key => state[key] && typeof state[key] === 'object' && !Array.isArray(state[key])) ? 'rakudai' : null;
}
function isSharedMvuState(state) {
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  return Boolean(object(state) && state.系统?.结构版本 === 4 &&
    [state.系统, state.场景, state.玩家, state.人际].every(object) &&
    (resolveMvuWorld(state) || state.系统.开局状态 === '待建档' && state.系统.作品 == null));
}
function isRakudaiMvuState(state) {
  return isSharedMvuState(state) && resolveMvuWorld(state) === 'rakudai';
}
function hasBlazerAbility(state) {
  const ability = state?.玩家?.伐刀能力;
  return isSharedMvuState(state) && state.系统.开局状态 === '已建档' &&
    ability !== null && typeof ability === 'object' && !Array.isArray(ability);
}
function hasBlazerGrowth(state) {
  const attributes = state?.玩家?.六维;
  return hasBlazerAbility(state) && attributes !== null && typeof attributes === 'object' && !Array.isArray(attributes);
}

function repairRakudaiMvuStructure(state, { legacyRequests = true } = {}) {
  // 学战只补已明确建立的成长账本，不因觉醒或换装备自动创建经验。
  if (!isRakudaiMvuState(state) && !(hasBlazerGrowth(state) && Object.hasOwn(state.玩家, '成长'))) return state;
  legacyRequests &&= resolveMvuWorld(state) === 'rakudai';
  const player = state.玩家;
  if (!Object.hasOwn(player, '成长')) {
    return { ...state, 玩家: { ...player, 成长: { 经验: { 魔力控制: 0, 体能: 0, 魔力量: 0 }, ...(legacyRequests ? { 申请: {} } : {}) } } };
  }
  const growth = player.成长;
  if (growth === null || typeof growth !== 'object' || Array.isArray(growth)) return state;
  let next = growth;
  function fill(field, value) {
    if (next === growth) next = { ...growth };
    next[field] = value;
  }
  if (!Object.hasOwn(growth, '经验')) fill('经验', { 魔力控制: 0, 体能: 0, 魔力量: 0 });
  else if (growth.经验 !== null && typeof growth.经验 === 'object' && !Array.isArray(growth.经验)) {
    let experience = growth.经验;
    for (const axis of ['魔力控制', '体能', '魔力量']) if (!Object.hasOwn(experience, axis)) {
      if (experience === growth.经验) experience = { ...growth.经验 };
      experience[axis] = 0;
    }
    if (experience !== growth.经验) fill('经验', experience);
  }
  // N02 的父容器兼容仍保留；新规则不创建或兑现申请。
  if (legacyRequests && !Object.hasOwn(growth, '申请')) fill('申请', {});
  return next === growth ? state : { ...state, 玩家: { ...player, 成长: next } };
}

// 只修复已被 MVU 解析的对象型 add/replace 批次；不猜字段、不改原状态或业务校验。
function normalizeRakudaiMvuCommands(commands, state) {
  if (!Array.isArray(commands) || !commands.length) return commands;
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  const reserved = key => ['__proto__', 'prototype', 'constructor'].includes(key);
  const safeValue = value => value === null || ['string', 'boolean'].includes(typeof value) ||
    typeof value === 'number' && Number.isFinite(value) ||
    value && typeof value === 'object' && Object.entries(value).every(([key, child]) => !reserved(key) && safeValue(child));
  const commandPath = parts => parts.map(part => '[' + JSON.stringify(part) + ']').join('');
  const pointer = parts => '/' + parts.map(part => part.replace(/~/g, '~0').replace(/\//g, '~1')).join('/');
  const commandFor = (original, op, parts) => ({ ...original, type: op.op === 'replace' ? 'set' : 'insert',
    full_match: JSON.stringify(op), args: op.op === 'replace' ? [commandPath(parts), JSON.stringify(op.value)] :
      [commandPath(parts.slice(0, -1)), /^\d+$/.test(parts.at(-1)) ? parts.at(-1) : JSON.stringify(parts.at(-1)), JSON.stringify(op.value)] });
  // 只复制命中的父路径；不为一次新人物补丁深拷贝全部历史与 $internal 镜像。
  const draft = object(state) ? { ...state } : null, groups = new Map(), rows = [];
  try {
    for (const command of commands) {
      if (command?.reason !== 'json_patch') return commands;
      const op = JSON.parse(command.full_match);
      if (!['add', 'replace'].includes(op?.op) || typeof op.path !== 'string' || !op.path.startsWith('/') ||
          /~(?![01])/.test(op.path) || !Object.hasOwn(op, 'value') || !safeValue(op.value)) return commands;
      const parts = op.path.slice(1).split('/').map(part => part.replace(/~1/g, '/').replace(/~0/g, '~'));
      if (parts.length < 2 || !['玩家', '场景', '人际'].includes(parts[0]) || parts.some(part => !part || reserved(part))) return commands;
      const expected = commandFor(command, op, parts);
      // 其他监听器已经修正的命令不从 full_match 还原，避免覆盖它们的处理结果。
      if (command.type !== expected.type || JSON.stringify(command.args) !== JSON.stringify(expected.args)) return commands;
      let original = state, parent = draft, missing;
      for (let index = 0; index < parts.length; index++) {
        const key = parts[index], last = index === parts.length - 1;
        if (!object(parent)) return commands; // null、原始值和数组父级均不自动覆盖或猜类型。
        if (!missing) {
          if (!object(original)) return commands;
          if (!Object.hasOwn(original, key)) missing = parts.slice(0, index + 1);
          else original = original[key];
        }
        if (last) {
          // 已有容器的整对象替换保留原命令语义，不在此展开、合并或重新排序。
          if (!missing && (original !== null && typeof original === 'object' || op.value !== null && typeof op.value === 'object')) return commands;
          parent[key] = structuredClone(op.value);
        } else {
          if (!Object.hasOwn(parent, key)) parent[key] = {};
          else if (object(parent[key])) parent[key] = { ...parent[key] };
          parent = parent[key];
        }
      }
      const groupKey = missing ? pointer(missing) : null;
      if (groupKey && !groups.has(groupKey)) groups.set(groupKey, { parts: missing, first: rows.length });
      rows.push({ command, groupKey });
    }
  } catch (_) { return commands; }
  let changed = false;
  const result = rows.flatMap(({ command, groupKey }, index) => {
    if (!groupKey) return [command];
    const group = groups.get(groupKey);
    if (group.first !== index) { changed = true; return []; }
    const value = group.parts.reduce((node, key) => node[key], draft);
    const op = { op: 'add', path: groupKey, value };
    const next = commandFor(command, op, group.parts);
    if (next.type === command.type && JSON.stringify(next.args) === JSON.stringify(command.args)) return [command];
    changed = true;
    return [next];
  });
  return changed ? result : commands;
}

// 本卡的 MVU 兼容层；补缺失经验容器/零初值，兼容旧申请父容器，不注册 Zod、不调用模型。
// MVU 61010dab: STARTED 后读取 schema；strictSet 只关闭 set 的旧二元组解释。
function rakudaiMvuScopes(scopes = []) {
  const result = [];
  for (const scope of scopes) {
    for (const resolve of [() => scope, () => scope?.parent, () => scope?.top]) {
      try { const value = resolve(); if (value && !result.includes(value)) result.push(value); } catch (_) {}
    }
  }
  return result;
}

function rakudaiMvuRuntime(scopes = []) {
  const entries = rakudaiMvuScopes(scopes).flatMap(scope => {
    try { return [{ boot: scope.__RK_MVU_GUARD_BOOT_V4__, guard: scope.__RK_MVU_GUARD_V4__ || scope.__RK_MVU_GUARD_V3__ }]; } catch (_) { return []; }
  });
  const entry = entries.find(item => item.boot) || entries.find(item => item.guard);
  if (!entry) return { mode: 'native', guard: null, boot: null };
  const { boot, guard } = entry;
  if (boot?.state === 'loading') return { mode: 'loading', boot, guard: guard || null };
  if (boot?.state === 'failed') return { mode: 'failed', boot, guard: guard || null };
  if (boot && (!guard || boot.state !== 'ready' || boot.guard !== guard)) return { mode: 'failed', boot, guard: guard || null };
  // 老版配套约束没有 boot 标记；真实 guard 仍表示 Zod 路径，不冒充原生模式。
  return { mode: 'zod', boot: boot || null, guard: guard || null };
}

function createRakudaiNativeSchema(state, previous) {
  function build(value, old, root = false) {
    if (Array.isArray(value)) {
      return { type: 'array', extensible: true, recursiveExtensible: true,
        elementType: value.length ? build(value[0], old?.elementType) : { type: 'any' },
        ...(old?.template !== undefined ? { template: structuredClone(old.template) } : {}) };
    }
    if (value && typeof value === 'object') {
      const properties = Object.fromEntries(Object.entries(value)
        .filter(([key]) => key !== '$internal' && key !== '$meta')
        .map(([key, child]) => [key, { ...build(child, old?.properties?.[key]), required: root }]));
      return { type: 'object', properties, extensible: !root, recursiveExtensible: !root,
        ...(old?.template !== undefined ? { template: structuredClone(old.template) } : {}) };
    }
    const type = typeof value;
    return { type: ['string', 'number', 'boolean'].includes(type) ? type : 'any' };
  }
  const schema = build(state, previous, true);
  schema.strictSet = true;
  schema.strictTemplate = previous?.strictTemplate ?? false;
  schema.concatTemplateArray = previous?.concatTemplateArray ?? true;
  return schema;
}

function prepareRakudaiNativeMvu(data, scopes = [], { repairStructure = true } = {}) {
  const runtime = rakudaiMvuRuntime(scopes);
  if (repairStructure && data?.stat_data) data.stat_data = repairRakudaiMvuStructure(data.stat_data,
    { legacyRequests: runtime.guard?.growthProtocol !== 'final-values-v1' });
  if (runtime.mode === 'native' && isSharedMvuState(data?.stat_data)) {
    data.schema = createRakudaiNativeSchema(data.stat_data, data.schema);
  }
  return data;
}

async function installRakudaiNativeMvu(W, options = {}) {
  const slot = '__RK_MVU_NATIVE_N01__';
  const configured = options.acceptState;
  if (configured !== undefined && typeof configured !== 'function') throw new TypeError('acceptState 必须是同步状态判定函数。');
  const existing = W[slot];
  if (existing?.version === 'N04' && existing.dorm === 'D01' && existing.worlds === 'W02' && existing.capabilities === 'H01' && existing.state !== 'failed' &&
      (configured === undefined || typeof existing.setAcceptState === 'function')) {
    if (configured !== undefined) existing.setAcceptState(configured);
    return existing;
  }
  W[slot]?.destroy?.();
  const marker = { version: 'N04', dorm: 'D01', worlds: 'W02', capabilities: 'H01', state: 'loading', destroy: null };
  let acceptState = configured || (() => true);
  // 重复安装可以收紧/更新本监听的门禁；未传选项的旧调用不会清掉已配置门禁。
  marker.setAcceptState = predicate => {
    if (typeof predicate !== 'function') throw new TypeError('acceptState 必须是同步状态判定函数。');
    acceptState = predicate;
  };
  const accepted = state => acceptState(state) === true;
  W[slot] = marker;
  let disposed = false, listener = null, commandListener = null, endListener = null;
  function destroy() {
    disposed = true; listener?.stop(); commandListener?.stop(); endListener?.stop();
    if (W[slot] === marker) delete W[slot];
    W.removeEventListener?.('pagehide', destroy);
  }
  marker.destroy = destroy;
  W.addEventListener?.('pagehide', destroy, { once: true });
  function helper(name) {
    if (typeof W[name] === 'function') return W[name].bind(W);
    if (typeof W.TavernHelper?.[name] === 'function') return W.TavernHelper[name].bind(W.TavernHelper);
    throw new Error('原生 MVU 兼容缺少酒馆助手接口：' + name);
  }
  try {
    await helper('waitGlobalInitialized')('Mvu');
    if (disposed) return marker;
    const scopes = rakudaiMvuScopes([W]);
    const H = [...scopes].reverse().find(scope => { try { return scope.SillyTavern?.getContext; } catch (_) { return false; } });
    if (!H) throw new Error('原生 MVU 兼容未连接当前酒馆。');
    const initial = H.SillyTavern.getContext();
    const owner = { characterId: initial.characterId, groupId: initial.groupId ?? null };
    if (owner.characterId == null && owner.groupId == null) throw new Error('请在角色聊天中加载原生 MVU 兼容。');
    const mvu = W.Mvu || H.Mvu;
    if (!mvu?.events?.VARIABLE_UPDATE_STARTED) throw new Error('MVU 缺少变量更新开始事件。');
    const owned = () => {
      if (disposed) return false;
      const current = H.SillyTavern.getContext();
      return current.characterId === owner.characterId && (current.groupId ?? null) === owner.groupId;
    };
    listener = helper('eventOn')(mvu.events.VARIABLE_UPDATE_STARTED, variables => {
      if (!owned() || !accepted(variables?.stat_data)) return;
      prepareRakudaiNativeMvu(variables, scopes);
    });
    if (mvu.events.COMMAND_PARSED) commandListener = helper('eventOn')(mvu.events.COMMAND_PARSED, (variables, commands, content) => {
      if (!owned() || !accepted(variables?.stat_data) || !isSharedMvuState(variables?.stat_data)) return;
      const world = resolveMvuWorld(variables.stat_data);
      const chat = H.SillyTavern.getContext().chat || [], replies = chat.flatMap((message, index) => !message.is_user && message.mes === content ? [index] : []);
      const resting = /^(?:宿舍)?休息[。！!\s]*$/.test(chat.slice(0, replies.length === 1 ? replies[0] : chat.length).findLast(message => message.is_user)?.mes?.trim() || ''), inDorm = variables.stat_data.场景?.宿舍 === true;
      const normalized = normalizeRakudaiMvuCommands(commands.filter(command => {
        if (world === 'rakudai' && resting && !inDorm) return false;
        if (world === 'asterisk' && command.reason !== 'json_patch') return false;
        let patch; try { patch = JSON.parse(command.full_match); if (!patch || typeof patch !== 'object') return false; } catch (_) { return world !== 'asterisk' && !inDorm && typeof variables.stat_data.场景?.宿舍 !== 'boolean'; }
        if (world === 'asterisk' && !['add', 'replace', 'remove'].includes(patch.op)) return false;
        const locked = path => path === '' || path === '/' || path === '/系统' || path?.startsWith('/系统/') || world === 'asterisk' && (path === '/玩家' || /^\/玩家\/综合初评(\/|$)/.test(path) || /^\/场景\/(路线|选拔赛|七星剑斗祭|宿舍)(\/|$)/.test(path) || path === '/场景/当前卷' && patch.value !== null);
        if (locked(patch.path) || patch.op === 'move' && locked(patch.from)) return false;
        if (world === 'asterisk') return patch.path !== '/场景';
        const protectedPath = path => typeof path !== 'string' || !path.startsWith('/') || path.includes('//') || path.endsWith('/') || ['/场景', '/场景/宿舍'].includes(path) || path.startsWith('/场景/宿舍/') || resting && replies.length !== 1 && (path === '/场景/时间' || path.startsWith('/场景/时间/')) || inDorm && (path === '/场景/地点' || path.startsWith('/场景/地点/'));
        if (patch.path === '/场景/宿舍') return inDorm && resting && replies.length === 1 && ['add', 'replace'].includes(patch.op) && patch.value === false;
        return !protectedPath(patch.path) && !(patch.op === 'move' && protectedPath(patch.from));
      }), variables.stat_data);
      if (normalized !== commands) commands.splice(0, commands.length, ...normalized);
    });
    if (mvu.events.VARIABLE_UPDATE_ENDED) endListener = helper('eventOn')(mvu.events.VARIABLE_UPDATE_ENDED, (variables, previous) => {
      if (!owned() || !accepted(previous?.stat_data) || !isSharedMvuState(previous?.stat_data)) return;
      // 以更新前的作品判断；legacy父对象替换同样不能借当前标记绕过保护。
      const before = previous.stat_data;
      if (variables.stat_data && typeof variables.stat_data === 'object' && !Array.isArray(variables.stat_data)) {
        const system = variables.stat_data.系统;
        if (!system || typeof system !== 'object' || Array.isArray(system)) variables.stat_data.系统 = structuredClone(before.系统);
        else if (Object.hasOwn(before.系统, '作品')) system.作品 = before.系统.作品;
        else delete system.作品;
      }
      if (!isSharedMvuState(variables.stat_data) || resolveMvuWorld(before) === 'asterisk' && !hasAsteriskNativeContract(variables.stat_data)) {
        variables.stat_data = structuredClone(before);
        variables.display_data = structuredClone(previous.display_data || {});
        variables.delta_data = {};
        marker.lastRejected = '本轮补丁破坏必要档案字段，已保留更新前的状态。';
      } else {
        if (variables.display_data?.系统 && typeof variables.display_data.系统 === 'object') delete variables.display_data.系统.作品;
        if (variables.delta_data?.系统 && typeof variables.delta_data.系统 === 'object') delete variables.delta_data.系统.作品;
      }
    });
    marker.state = 'ready';
  } catch (error) {
    if (!disposed) { marker.state = 'failed'; marker.message = error?.message || '原生 MVU 兼容启动失败。'; }
  }
  return marker;
}

window.RakudaiMvuNative = { version: "N04", runtime: rakudaiMvuRuntime, prepare: prepareRakudaiNativeMvu, install: installRakudaiNativeMvu };
void installRakudaiNativeMvu(window);
})();
